WITH ValidEmployees AS (SELECT * FROM employees WHERE level IN ('L4', 'L1')), agg AS (SELECT job_title, manager_id, ROUND((100 * SUM(CASE WHEN job_title = 'Designer' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_designer, COUNT(CASE WHEN job_title = 'Analyst' THEN 1 END) analyst_count FROM ValidEmployees GROUP BY job_title, manager_id) SELECT job_title, pct_designer, analyst_count FROM agg WHERE pct_designer > 78 ORDER BY analyst_count
